    // Twin A: hold, stream 20, jump to live.
    final held = _FollowTestService()
      ..msgs = _msgs(30)
      ..streaming = true;
    await _pump(tester, held);
    await _dragTowardHistory(tester, 400);
    held.append(20);
    await tester.pump(const Duration(milliseconds: 100));
