    if (!clampActive && !_userNearBottom) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      // The screen may be gone by the time the frame lands (mode switch,
      // page swap) — a defunct State has no usable context.
      if (!mounted) return;
